{"solution_py":""""Rotate refresh tokens in a mutable token record store."""
from __future__ import annotations

from typing import Any


def _is_true(value: Any) -> bool:
    if isinstance(value, str):
        return value.lower() in {"true", "yes", "used", "revoked"}
    return bool(value)


def _family_key(record: dict[str, Any]) -> str | None:
    for key in ("family", "family_id", "familyId", "token_family"):
        if key in record:
            return key
    return None


def _is_revoked(record: dict[str, Any]) -> bool:
    if _is_true(record.get("revoked", False)):
        return True
    return str(record.get("status", "")).lower() == "revoked"


def _is_used(record: dict[str, Any]) -> bool:
    if _is_true(record.get("used", False)):
        return True
    return str(record.get("status", "")).lower() == "used"


def rotate_refresh(records: dict[str, dict[str, Any]], token: str, new_token: str) -> str:
    """Consume ``token`` and issue ``new_token`` from the same token family.

    A token may be consumed only once.  Seeing a consumed token again revokes
    every record in its family, which makes replay detectable by callers.
    """
    try:
        record = records[token]
    except (KeyError, TypeError):
        raise ValueError("unknown refresh token") from None

    if not isinstance(record, dict):
        raise ValueError("invalid refresh token record")
    if not isinstance(new_token, str) or not new_token or new_token in records:
        raise ValueError("invalid replacement refresh token")
    if new_token == token:
        raise ValueError("replacement token must differ")

    family_key = _family_key(record)
    family_value = record.get(family_key) if family_key else None

    related: list[dict[str, Any]] = []
    if family_key is not None:
        for candidate in records.values():
            if not isinstance(candidate, dict):
                continue
            if (
                _family_key(candidate) == family_key
                and candidate.get(family_key) == family_value
            ):
                related.append(candidate)
    else:
        related = [record]

    if _is_used(record):
        # Validate the affected records before changing any of them.
        if any(not isinstance(candidate, dict) for candidate in related):
            raise ValueError("invalid refresh token record")
        for candidate in related:
            candidate["revoked"] = True
            if "status" in candidate:
                candidate["status"] = "revoked"
        raise ValueError("refresh token replayed")

    if _is_revoked(record):
        raise ValueError("refresh token revoked")

    replacement = dict(record)
    replacement["used"] = False
    if "revoked" in replacement:
        replacement["revoked"] = False
    if "status" in replacement:
        replacement["status"] = "active"
    for parent_key in ("parent", "parent_token", "parentToken"):
        if parent_key in replacement:
            replacement[parent_key] = token
            break

    # All checks are complete before either the old record or the store is
    # changed.
    record["used"] = True
    if "status" in record:
        record["status"] = "used"
    records[new_token] = replacement
    return new_token
